/* Matematica – Applicazioni professionali – version italienne, générée par outils/traduction.js depuis data.js (mêmes épreuves, même ordre). a[0] = richtige Antwort. */
window.OBJ = [{"code":"Mod. 4","t":"Proporzionalità e regola del tre","g":"Prevedere una quantità, un tempo o un costo a partire da una situazione nota","col":"teal","ic":"ratio","ch":[{"k":"qcm","q":"Quando due grandezze sono direttamente proporzionali?","a":["Quando una raddoppia, raddoppia anche l’altra","Quando una raddoppia, l’altra si dimezza","Quando la loro somma resta sempre la stessa","Quando la loro differenza resta sempre la stessa"],"ex":"Stesso senso, stesso rapporto: se si moltiplica una per un numero, l’altra viene moltiplicata per lo stesso numero.","ref":"Lezione 4.1"},{"k":"tf","q":"Un trasporto fatturato con un forfait fisso più un prezzo al chilometro è direttamente proporzionale alla distanza.","v":false,"ex":"No: il forfait si paga una sola volta, quindi 200 km non costano il doppio di 100 km.","ref":"Lezione 4.1"},{"k":"num","q":"5 cartoni identici pesano 40 kg. Quanto pesano 8 cartoni?","n":64,"tol":0,"u":"kg","ex":"1 cartone: 40 ÷ 5 = 8 kg. 8 cartoni: 8 × 8 = 64 kg.","ref":"Lezione 4.1"},{"k":"num","q":"15 cartoni identici pesano insieme 180 kg. Qual è il peso di 22 cartoni?","n":264,"tol":0,"u":"kg","ex":"1 cartone: 180 ÷ 15 = 12 kg. 22 cartoni: 22 × 12 = 264 kg.","ref":"Lezione 4.1"},{"k":"num","q":"9 palette contengono insieme 432 cartoni. Quanti cartoni contengono 15 palette identiche?","n":720,"tol":0,"u":"cartoni","ex":"1 paletta: 432 ÷ 9 = 48 cartoni. 15 palette: 15 × 48 = 720 cartoni.","ref":"Lezione 4.1"},{"k":"case","s":"Il caposquadra della piattaforma Logimax pianifica la giornata di domani. Oggi 6 preparatori hanno trattato 420 commissioni. Domani lavoreranno 8 preparatori allo stesso ritmo.","q":"Quante commissioni può trattare la squadra domani?","a":["560 commissioni","490 commissioni","600 commissioni","630 commissioni"],"ex":"1 preparatore: 420 ÷ 6 = 70 commissioni. 8 preparatori: 8 × 70 = 560 commissioni.","ref":"Lezione 4.1"},{"k":"num","q":"2 magazzinieri sistemano una consegna in 6 ore. Quante ore servono a 3 magazzinieri che lavorano allo stesso ritmo?","n":4,"tol":0,"u":"ore","ex":"Lavoro totale: 2 × 6 = 12 ore di lavoro. Con 3 magazzinieri: 12 ÷ 3 = 4 ore.","ref":"Lezione 4.2"},{"k":"num","q":"6 collaboratori terminano un inventario in 8 ore. Quante ore servono a 12 collaboratori allo stesso ritmo?","n":4,"tol":0,"u":"ore","ex":"Lavoro totale: 6 × 8 = 48 ore di lavoro. 48 ÷ 12 = 4 ore.","ref":"Lezione 4.2"},{"k":"case","s":"Alla rampa di Transvalor SA 4 carrelli elevatori scaricano una grande consegna in 6 ore. Per liberare prima la rampa, il responsabile impiega 8 carrelli identici.","q":"Quanto dura lo scarico con 8 carrelli?","a":["3 ore","12 ore","4 ore","2 ore"],"ex":"Proporzionalità inversa: 4 × 6 = 24 ore-carrello. 24 ÷ 8 = 3 ore. Più carrelli, quindi meno tempo.","ref":"Lezione 4.2"},{"k":"num","q":"5 carrelli scaricano un camion in 50 minuti. Quanti minuti servono con 10 carrelli identici?","n":25,"tol":0,"u":"minuti","ex":"5 × 50 = 250 minuti-carrello. 250 ÷ 10 = 25 minuti.","ref":"Lezione 4.2"},{"k":"sort","q":"Classifichi ogni situazione: direttamente o inversamente proporzionale?","c":["Diretta","Inversa"],"it":[["Numero di cartoni identici e peso totale",0],["Numero di persone e durata di un inventario",1],["Velocità e tempo di percorrenza su una distanza fissa",1],["Numero di etichette e prezzo totale",0],["Numero di palette e superficie a terra",0],["Numero di carrelli e tempo di scarico",1]],"ex":"Diretta: stesso senso. Inversa: senso contrario (più persone o più velocità, meno tempo).","ref":"Lezione 4.2"},{"k":"tf","q":"Nella proporzionalità inversa il prodotto delle due grandezze resta costante.","v":true,"ex":"Sì: 2 magazzinieri × 6 h = 3 magazzinieri × 4 h = 12 ore di lavoro.","ref":"Lezione 4.2"},{"k":"fill","q":"Nella proporzionalità diretta è il ___ delle due grandezze che resta costante.","a":["rapporto","prodotto","totale","scarto"],"ex":"Diretta: il rapporto è costante (il peso di un cartone, il prezzo di un articolo). Inversa: è il prodotto.","ref":"Lezione 4.2"},{"k":"num","q":"Un camion consuma 30 L per 100 km. Quanti litri consuma per 250 km?","n":75,"tol":0,"u":"L","ex":"1 km: 30 ÷ 100 = 0.3 L. 250 km: 0.3 × 250 = 75 L.","ref":"Lezione 4.3"},{"k":"case","s":"Un autista di TransLéman deve consegnare a 365 km dal deposito. Il suo camion consuma 28 L di diesel per 100 km. Vuole sapere quanto carburante prevedere per l’andata.","q":"Quale quantità di carburante bisogna prevedere?","a":["102.2 L","93.8 L","112.0 L","130.4 L"],"ex":"1 km: 28 ÷ 100 = 0.28 L. 365 km: 0.28 × 365 = 102.2 L.","ref":"Lezione 4.3"},{"k":"num","q":"Un veicolo viaggia a 60 km/h. Quanti minuti gli servono per percorrere 150 km?","n":150,"tol":0,"u":"minuti","ex":"60 km in 60 min, quindi 1 km al minuto. 150 km: 150 min, cioè 2 h 30 min.","ref":"Lezione 4.3"},{"k":"qcm","q":"Una durata di 5.5 h corrisponde a…","a":["5 h 30 min","5 h 50 min","5 h 05 min","5 h 55 min"],"ex":"1 ora = 60 minuti, non 100: 0.5 h = 30 min. 5.5 h = 5 h 30 min.","ref":"Lezione 4.3"},{"k":"case","s":"Un camion di consegna ha percorso 240 km in 4 ore a velocità costante. Gli resta un giro di 330 km alla stessa velocità e il pianificatore vuole l’ora d’arrivo.","q":"Quanto tempo serve per 330 km?","a":["5 h 30 min","4 h 50 min","5 h 15 min","6 h 00 min"],"ex":"240 km in 240 min, quindi 1 km al minuto. 330 km: 330 min = 5 h 30 min.","ref":"Lezione 4.3"},{"k":"num","q":"750 etichette costano CHF 45.00. Quanti franchi costano 1’200 etichette allo stesso prezzo unitario?","n":72,"tol":0,"u":"CHF","ex":"1 etichetta: 45 ÷ 750 = CHF 0.06. 1’200 etichette: 1’200 × 0.06 = CHF 72.00.","ref":"Lezione 4.3"},{"k":"case","s":"Il magazziniere di Logipack ordina film d’imballaggio. L’ultimo lotto di 400 film è costato CHF 68.00. Questa volta ne servono 650, allo stesso prezzo unitario.","q":"Quale sarà l’importo dell’ordinazione?","a":["CHF 110.50","CHF 102.00","CHF 115.60","CHF 119.00"],"ex":"1 film: 68 ÷ 400 = CHF 0.17. 650 film: 650 × 0.17 = CHF 110.50. Si tiene il prezzo unitario esatto e si arrotonda solo alla fine.","ref":"Lezione 4.3"},{"k":"order","q":"Metta in ordine il metodo della riduzione all’unità.","a":["Individuare la grandezza nota e la grandezza cercata","Dividere per trovare il valore per 1 unità","Moltiplicare per il numero di unità richiesto","Controllare che il risultato vada nel senso giusto"],"ex":"Si divide per trovare l’unità, si moltiplica per trovare il risultato, poi si verifica il senso.","ref":"Lezione 4.1"},{"k":"num","q":"2 preparatori trattano 120 pacchi in 3 ore. Quanti pacchi trattano 4 preparatori in 2 ore allo stesso ritmo?","n":160,"tol":0,"u":"colli","ex":"Cadenza: 120 ÷ 2 ÷ 3 = 20 pacchi per persona e per ora. 20 × 4 × 2 = 160 pacchi.","ref":"Lezione 4.4"},{"k":"case","s":"Presso Distrivaud 4 preparatori hanno trattato 560 pacchi in 7 ore. Domani la squadra conterà 6 preparatori, ma solo per 5 ore.","q":"Quanti pacchi può trattare la squadra domani?","a":["600 pacchi","560 pacchi","630 pacchi","720 pacchi"],"ex":"Cadenza: 560 ÷ 4 ÷ 7 = 20 pacchi per persona e per ora. 20 × 6 × 5 = 600 pacchi.","ref":"Lezione 4.4"},{"k":"case","s":"Ieri 6 collaboratori hanno preparato 900 pacchi in 5 ore. Oggi devono partire 1’440 pacchi e restano solo 4 ore prima del passaggio del vettore.","q":"Quanti collaboratori bisogna impiegare?","a":["12 collaboratori","10 collaboratori","14 collaboratori","16 collaboratori"],"ex":"Cadenza: 900 ÷ 6 ÷ 5 = 30 pacchi per persona e per ora. 1’440 ÷ (30 × 4) = 12 collaboratori.","ref":"Lezione 4.4"},{"k":"case","s":"Un preparatore tratta 25 pacchi all’ora. Una commissione urgente di 1’000 pacchi dev’essere pronta in 6 ore. Il caposquadra calcola il personale necessario.","q":"Quanti preparatori bisogna prevedere?","a":["7 preparatori","6 preparatori","8 preparatori","5 preparatori"],"ex":"1’000 ÷ (25 × 6) = 6.67. Si arrotonda per eccesso: non si può impiegare una frazione di persona, quindi 7 preparatori.","ref":"Lezione 4.4"},{"k":"num","q":"Un camion consuma 24 L per 100 km. Effettua 3 tragitti di 175 km. Quanti litri consuma in totale?","n":126,"tol":0,"u":"L","ex":"Distanza totale: 3 × 175 = 525 km. 0.24 × 525 = 126 L.","ref":"Lezione 4.4"},{"k":"odd","q":"Trovi l’intruso: quale di queste situazioni NON è direttamente proporzionale?","a":["Numero di carrellisti e durata dello scarico","Numero di palette e superficie a terra","Tempo di funzionamento e pezzi prodotti","Numero di etichette e prezzo totale"],"ex":"Più carrellisti, meno tempo: è una proporzionalità inversa.","ref":"Lezione 4.2"},{"k":"match","q":"Abbini ogni dato del mestiere al suo valore per 1 unità.","p":[["30 L/100 km","0.3 L per km"],["60 km/h","1 km al minuto"],["120 pacchi in 8 min","15 pacchi al minuto"],["CHF 45.00 le 750 etichette","CHF 0.06 per etichetta"]],"ex":"Si divide per tornare a 1 unità: 30 ÷ 100, 60 ÷ 60, 120 ÷ 8, 45 ÷ 750.","ref":"Lezione 4.3"},{"k":"multi","q":"Quali situazioni sono inversamente proporzionali?","good":["Numero di persone e durata di una sistemazione","Numero di carrelli e tempo di scarico","Velocità e tempo di percorrenza su 200 km"],"bad":["Numero di cartoni e peso totale","Numero di etichette e prezzo totale"],"ex":"Inversa: quando una aumenta, l’altra diminuisce (il prodotto resta costante).","ref":"Lezione 4.2"},{"k":"case","s":"Due magazzinieri hanno sistemato una consegna in 6 ore. Per la prossima, identica, saranno in tre. Un collega annuncia: «Ci vorranno 9 ore.»","q":"Che cosa gli risponde?","a":["No: 12 ore di lavoro ÷ 3 = 4 ore","Sì: 6 ÷ 2 × 3 = 9 ore di lavoro","No: 6 − 1 = 5 ore, una persona in più","Sì: con più persone il lavoro dura di più"],"ex":"Errore classico: applicare la proporzionalità diretta. Con più persone il lavoro non può durare di più. 2 × 6 = 12; 12 ÷ 3 = 4 h.","ref":"Lezione 4.2"},{"k":"case","s":"Un nastro trasportatore del centro di smistamento sposta 840 pacchi in 35 minuti. Il responsabile vuole sapere quanti ne tratta in 50 minuti, allo stesso ritmo.","q":"Quanti pacchi passano in 50 minuti?","a":["1’200 pacchi","1’050 pacchi","1’260 pacchi","1’400 pacchi"],"ex":"1 minuto: 840 ÷ 35 = 24 pacchi. 50 minuti: 24 × 50 = 1’200 pacchi.","ref":"Lezione 4.3"}]},{"code":"Mod. 5","t":"Percentuali avanzate","g":"Leggere e calcolare tassi, sconti, aumenti e diminuzioni","col":"indigo","ic":"percent","ch":[{"k":"qcm","q":"Che cosa significa «per cento»?","a":["Su 100","Per 100","Diviso per 10","Su 1’000"],"ex":"Una percentuale indica quante parti si avrebbero se il totale fosse riportato a 100.","ref":"Lezione 5.1"},{"k":"num","q":"Su 200 pacchi ricevuti, 6 sono danneggiati. Qual è il tasso di rottura in %?","n":3,"tol":0,"u":"%","ex":"6 ÷ 200 = 0.03; 0.03 × 100 = 3 %.","ref":"Lezione 5.1"},{"k":"case","s":"Al ricevimento di Logiplus il controllore ha contato 12 pacchi danneggiati su 300 pacchi ricevuti stamattina. La responsabile qualità gli chiede il tasso di rottura.","q":"Qual è il tasso di rottura?","a":["4 %","4.2 %","12 %","0.04 %"],"ex":"Tasso di rottura = pacchi danneggiati ÷ pacchi ricevuti × 100 = 12 ÷ 300 × 100 = 4 %. Il totale di riferimento è quello dei pacchi ricevuti, non dei pacchi intatti.","ref":"Lezione 5.1"},{"k":"match","q":"Abbini ogni indicatore al suo calcolo (parte ÷ totale).","p":[["Tasso di rottura","Pacchi danneggiati ÷ pacchi ricevuti"],["Tasso d’errore di preparazione","Commissioni con errore ÷ commissioni preparate"],["Tasso di servizio","Articoli consegnati subito ÷ articoli ordinati"],["Tasso di ritorno","Pacchi rispediti ÷ pacchi spediti"]],"ex":"Stessa formula ovunque: parte ÷ totale × 100. Cambiano solo la parte e il totale.","ref":"Lezione 5.1"},{"k":"match","q":"Abbini ogni frazione alla sua percentuale.","p":[["1/2","50 %"],["1/4","25 %"],["1/10","10 %"],["1/100","1 %"]],"ex":"Frazione → numero decimale (0.5; 0.25; 0.1; 0.01) → × 100.","ref":"Lezione 5.1"},{"k":"tf","q":"Il risultato 0.03 corrisponde allo 0.03 %.","v":false,"ex":"Bisogna moltiplicare per 100: 0.03 = 3 %.","ref":"Lezione 5.1"},{"k":"case","s":"Inventario presso Stockalp: il software indica 4’850 pezzi di un articolo, ma il conteggio fisico ne trova 4’753. Il capodeposito vuole la differenza d’inventario in %.","q":"Qual è la differenza d’inventario?","a":["2 %","2.04 %","97 %","0.2 %"],"ex":"Differenza: 4’850 − 4’753 = 97. Riferimento: lo stock informatico. 97 ÷ 4’850 × 100 = 2 %.","ref":"Lezione 5.1"},{"k":"num","q":"Quanto fa il 15 % di 400 articoli?","n":60,"tol":0,"u":"articoli","ex":"10 % = 40, 5 % = 20; 15 % = 60. Oppure: 400 × 0.15 = 60.","ref":"Lezione 5.2"},{"k":"num","q":"Uno stock conta 400 articoli, di cui il 15 % di categoria A. Quanti articoli NON sono di categoria A?","n":340,"tol":0,"u":"articoli","ex":"400 × 0.15 = 60 articoli A; 400 − 60 = 340. Oppure direttamente 400 × 0.85 = 340.","ref":"Lezione 5.2"},{"k":"case","s":"La scaffalatura del deposito di Morges conta 250 ubicazioni. Il software indica che il 64 % è occupato. Il carrellista vuole sapere quante ubicazioni libere gli restano per il ricevimento.","q":"Quante ubicazioni sono libere?","a":["90 ubicazioni","160 ubicazioni","64 ubicazioni","36 ubicazioni"],"ex":"Libere: 100 % − 64 % = 36 %. 250 × 0.36 = 90 ubicazioni. Trappola: il 64 % di 250 dà le ubicazioni occupate (160).","ref":"Lezione 5.2"},{"k":"qcm","q":"Come si scrive 7.5 % come numero decimale?","a":["0.075","0.75","7.5","0.0075"],"ex":"Si divide per 100: il punto si sposta di due posizioni verso sinistra.","ref":"Lezione 5.2"},{"k":"num","q":"Bisogna controllare il 2.5 % di un lotto di 1’200 cartoni. Quanti cartoni bisogna controllare?","n":30,"tol":0,"u":"cartoni","ex":"1’200 × 0.025 = 30 cartoni.","ref":"Lezione 5.2"},{"k":"fill","q":"Per un aumento dell’8 % il coefficiente moltiplicatore è ___.","a":["1.08","1.8","0.92","0.08"],"ex":"Aumento del p %: × (1 + p ÷ 100) = × 1.08. Trappola: scrivere 1.8.","ref":"Lezione 5.3"},{"k":"num","q":"Un rotolo di film costa CHF 20.00. Il fornitore concede uno sconto del 5 %. Qual è il nuovo prezzo in CHF?","n":19,"tol":0,"u":"CHF","ex":"Coefficiente: 1 − 0.05 = 0.95. 20 × 0.95 = CHF 19.00.","ref":"Lezione 5.3"},{"k":"case","s":"Una prestazione di trasporto è fatturata CHF 50.00 IVA esclusa. La contabile di LogiSuisse deve aggiungere l’IVA dell’8.1 % per ottenere l’importo IVA inclusa.","q":"Qual è l’importo IVA inclusa?","a":["CHF 54.05","CHF 50.81","CHF 58.10","CHF 45.95"],"ex":"Coefficiente: 1 + 0.081 = 1.081. 50 × 1.081 = CHF 54.05.","ref":"Lezione 5.3"},{"k":"num","q":"Il prezzo di un trasporto passa da CHF 50.00 a CHF 55.00. Di quanti % è aumentato?","n":10,"tol":0,"u":"%","ex":"Differenza: 55 − 50 = 5. 5 ÷ 50 × 100 = 10 %. Si confronta sempre con il valore vecchio.","ref":"Lezione 5.3"},{"k":"case","s":"Il prezzo di una paletta di cinghie passa da CHF 80.00 a CHF 68.00 grazie a una nuova offerta. L’acquirente vuole conoscere la variazione in % per il suo rapporto.","q":"Qual è la variazione del prezzo?","a":["Diminuzione del 15 %","Diminuzione del 17.6 %","Diminuzione del 12 %","Aumento del 15 %"],"ex":"(68 − 80) ÷ 80 × 100 = −15 %: diminuzione del 15 %. Trappola: dividere per il valore nuovo (12 ÷ 68 = 17.6 %).","ref":"Lezione 5.3"},{"k":"qcm","q":"Per calcolare una variazione in %, si divide la differenza per…","a":["Il valore vecchio","Il valore nuovo","La somma dei due valori","100"],"ex":"Il valore di partenza è sempre il riferimento.","ref":"Lezione 5.3"},{"k":"sort","q":"Classifichi ogni coefficiente moltiplicatore: aumento o diminuzione?","c":["Aumento","Diminuzione"],"it":[["× 1.081 (IVA)",0],["× 0.95",1],["× 1.10",0],["× 0.90",1],["× 0.855",1],["× 1.025",0]],"ex":"Coefficiente superiore a 1: aumento. Inferiore a 1: diminuzione.","ref":"Lezione 5.3"},{"k":"case","s":"Un fornitore di cartoni concede a Logimax uno sconto del 10 % su un lotto a CHF 200.00, poi uno sconto fedeltà del 5 % sul prezzo già ridotto.","q":"Qual è il prezzo finale del lotto?","a":["CHF 171.00","CHF 170.00","CHF 172.50","CHF 180.00"],"ex":"200 × 0.90 × 0.95 = CHF 171.00. Gli sconti non si sommano: lo sconto totale è del 14.5 %, non del 15 %.","ref":"Lezione 5.4"},{"k":"tf","q":"Uno sconto del 10 % seguito da uno sconto del 5 % dà uno sconto totale del 15 %.","v":false,"ex":"Si moltiplicano i coefficienti: 0.90 × 0.95 = 0.855, cioè uno sconto del 14.5 %.","ref":"Lezione 5.4"},{"k":"num","q":"Uno stock di 1’000 pezzi aumenta del 10 %, poi diminuisce del 10 %. Quanti pezzi restano?","n":990,"tol":0,"u":"pezzi","ex":"1’000 × 1.10 = 1’100; 1’100 × 0.90 = 990. La diminuzione si applica a 1’100: non si torna a 1’000.","ref":"Lezione 5.4"},{"k":"case","s":"Grazie a un nuovo scanner il tasso d’errore di preparazione del magazzino è passato dal 5 % al 3.5 %. La direzione chiede di quanto è diminuito, in valore relativo.","q":"Di quanti % è diminuito il tasso d’errore?","a":["30 %","1.5 %","3.5 %","15 %"],"ex":"Differenza: 1.5 punti. Valore relativo: 1.5 ÷ 5 × 100 = 30 %.","ref":"Lezione 5.4"},{"k":"qcm","q":"Un tasso d’errore passa dal 5 % al 3.5 %. Di quanti punti percentuali è diminuito?","a":["1.5 punti","30 punti","3.5 punti","8.5 punti"],"ex":"5 − 3.5 = 1.5 punti. In valore relativo è una diminuzione del 30 %.","ref":"Lezione 5.4"},{"k":"case","s":"Un lotto di 2’000 articoli arriva al controllo qualità. L’8 % non è conforme. Tra gli articoli conformi, il 20 % parte per espresso, il resto con invio standard.","q":"Quanti articoli partono per espresso?","a":["368 articoli","400 articoli","320 articoli","1’472 articoli"],"ex":"Conformi: 2’000 × 0.92 = 1’840. Espresso: 1’840 × 0.20 = 368. Il 20 % si applica ai conformi, non al totale.","ref":"Lezione 5.4"},{"k":"order","q":"Metta in ordine il metodo per concatenare più percentuali.","a":["Suddividere il problema in tappe, nell’ordine dell’enunciato","Chiedersi a quale quantità si applica la percentuale","Calcolare il risultato della tappa","Usare questo risultato come base della tappa seguente"],"ex":"Ogni percentuale si applica al risultato della tappa precedente.","ref":"Lezione 5.4"},{"k":"odd","q":"Trovi l’intruso tra questi coefficienti.","a":["× 1.05","× 0.90","× 0.95","× 0.75"],"ex":"× 1.05 è un aumento del 5 %; gli altri sono diminuzioni (10 %, 5 %, 25 %).","ref":"Lezione 5.3"},{"k":"multi","q":"Quali affermazioni sono corrette?","good":["Il tasso di rottura si calcola sui pacchi ricevuti","Una variazione si confronta con il valore di partenza","Si moltiplicano i coefficienti di percentuali successive"],"bad":["Percentuali successive si sommano","Si divide la differenza per il valore nuovo"],"ex":"Chiedersi sempre «su quanto?» e non sommare mai percentuali successive.","ref":"Lezione 5.4"},{"k":"case","s":"In ottobre il sito di vendita online di Logiplus ha spedito 1’200 pacchi. 36 pacchi sono stati rispediti dai clienti. Il servizio clienti vuole il tasso di ritorno del mese.","q":"Qual è il tasso di ritorno?","a":["3 %","3.6 %","36 %","0.3 %"],"ex":"Pacchi rispediti ÷ pacchi spediti × 100 = 36 ÷ 1’200 × 100 = 3 %.","ref":"Lezione 5.1"},{"k":"num","q":"Una fattura ammonta a CHF 1’000.00 IVA esclusa. Qual è l’importo IVA inclusa con un’IVA dell’8.1 %, in CHF?","n":1081,"tol":0,"u":"CHF","ex":"1’000 × 1.081 = CHF 1’081.00.","ref":"Lezione 5.3"},{"k":"case","s":"Un cliente ha ordinato 480 articoli a Distrivaud. 456 hanno potuto essere consegnati subito, gli altri saranno consegnati più tardi. La responsabile calcola il tasso di servizio.","q":"Qual è il tasso di servizio?","a":["95 %","5 %","105.3 %","4.8 %"],"ex":"Articoli consegnati subito ÷ articoli ordinati × 100 = 456 ÷ 480 × 100 = 95 %.","ref":"Lezione 5.1"}]},{"code":"Mod. 6","t":"Tasso di riempimento e capacità","g":"Misurare l’occupazione di uno stock o di un veicolo e lo spazio restante","col":"violet","ic":"fill","ch":[{"k":"num","q":"Una scaffalatura conta 200 ubicazioni, di cui 150 occupate. Qual è il tasso d’occupazione in %?","n":75,"tol":0,"u":"%","ex":"150 ÷ 200 × 100 = 75 %.","ref":"Lezione 6.1"},{"k":"tf","q":"Il tasso d’occupazione e il tasso libero fanno sempre insieme il 100 %.","v":true,"ex":"Tasso libero = 100 % − tasso d’occupazione.","ref":"Lezione 6.1"},{"k":"case","s":"La scaffalatura per palette di Stockalp conta 320 ubicazioni. Stamattina 248 sono occupate. Il capodeposito prepara il suo rapporto settimanale.","q":"Qual è il tasso d’occupazione?","a":["77.5 %","22.5 %","72.0 %","129.0 %"],"ex":"248 ÷ 320 × 100 = 77.5 %. Il 22.5 % corrisponde al tasso libero.","ref":"Lezione 6.1"},{"k":"qcm","q":"A partire da quale tasso d’occupazione molte aziende fissano una soglia d’allarme?","a":["Circa l’85–90 %","Circa il 50 %","Esattamente il 100 %","Circa il 25–30 %"],"ex":"Un magazzino quasi pieno manca di flessibilità: la soglia d’allarme si situa spesso attorno all’85–90 %.","ref":"Lezione 6.1"},{"k":"case","s":"Il direttore di Logimax è fiero: il suo magazzino è occupato al 98 %. Eppure i preparatori si lamentano e da qualche settimana gli errori aumentano.","q":"Qual è il problema di un tasso così elevato?","a":["Non c’è più spazio per un ricevimento imprevisto","L’affitto del magazzino diventa più elevato","Le palette diventano più pesanti da sollevare","Il tasso libero supera allora il 100 %"],"ex":"Un magazzino quasi pieno manca di flessibilità: ricevimenti imprevisti difficili, spostamenti ed errori in aumento.","ref":"Lezione 6.1"},{"k":"tf","q":"Un tasso d’occupazione molto basso segnala superficie pagata ma inutilizzata.","v":true,"ex":"È l’altro estremo: si paga spazio per niente.","ref":"Lezione 6.1"},{"k":"num","q":"Un furgone ha un carico utile di 1’000 kg. Trasporta 800 kg. Qual è il suo tasso di carico in %?","n":80,"tol":0,"u":"%","ex":"800 ÷ 1’000 × 100 = 80 %.","ref":"Lezione 6.2"},{"k":"num","q":"Un camion ha un carico utile di 15 t. Trasporta 12 t. Qual è il suo tasso di carico in %?","n":80,"tol":0,"u":"%","ex":"12 ÷ 15 × 100 = 80 %. I due valori sono già in tonnellate.","ref":"Lezione 6.2"},{"k":"case","s":"Un furgone ha un carico utile di 3.5 t. Il fattorino ha caricato 2’800 kg di merci e vuole controllare il suo tasso di carico.","q":"Qual è il tasso di carico?","a":["80 %","0.8 %","125 %","8 %"],"ex":"Prima si converte: 3.5 t = 3’500 kg. 2’800 ÷ 3’500 × 100 = 80 %.","ref":"Lezione 6.2"},{"k":"sort","q":"Classifichi ogni capacità secondo la sua misura.","c":["Peso","Volume","Numero di unità"],"it":[["Carico utile di un camion",0],["Carico ammissibile di una paletta",0],["Volume utile di un container",1],["Capacità di una cisterna",1],["Posti paletta di un semirimorchio",2],["Vani di un magazzino automatico",2]],"ex":"Peso: kg, t. Volume: m³, L. Unità: palette, contenitori, vani.","ref":"Lezione 6.2"},{"k":"case","s":"Un camion di Transvalor carica cartoni d’imballaggio vuoti, molto voluminosi ma leggeri. L’autista si chiede quale limite raggiungerà per primo.","q":"Quale limite sarà raggiunto per primo?","a":["Il volume, molto prima del carico utile","Il carico utile, molto prima del volume","I due limiti esattamente nello stesso momento","Nessuno, il camion non sarà mai pieno"],"ex":"Merci leggere e voluminose riempiono lo spazio molto prima di raggiungere il carico utile.","ref":"Lezione 6.2"},{"k":"qcm","q":"Un calcolo dà 22 ÷ 26 × 100 = 84.615… %. Qual è il risultato arrotondato al decimo?","a":["84.6 %","84.7 %","84.0 %","85.0 %"],"ex":"Cifra dei centesimi: 1, quindi si tiene il decimo così com’è: 84.6 %.","ref":"Lezione 6.2"},{"k":"num","q":"Una scaffalatura di 320 ubicazioni ne conta 248 occupate. Quante ubicazioni sono disponibili?","n":72,"tol":0,"u":"ubicazioni","ex":"320 − 248 = 72 ubicazioni.","ref":"Lezione 6.3"},{"k":"case","s":"Il deposito di Logipack dispone di 400 ubicazioni per palette, occupate al 72 %. Per domani mattina è annunciata una consegna importante.","q":"Quante ubicazioni sono ancora disponibili?","a":["112 ubicazioni","288 ubicazioni","128 ubicazioni","28 ubicazioni"],"ex":"Quota libera: 100 % − 72 % = 28 %. 400 × 0.28 = 112 ubicazioni. Controllo: 288 occupate + 112 = 400.","ref":"Lezione 6.3"},{"k":"num","q":"Una cisterna da 2’000 L è riempita al 70 %. Quanti litri restano disponibili?","n":600,"tol":0,"u":"L","ex":"Quota libera: 30 %. 2’000 × 0.30 = 600 L. Controllo: 1’400 + 600 = 2’000 L.","ref":"Lezione 6.3"},{"k":"case","s":"Un container ha un volume utile di 67.7 m³. Le merci già caricate occupano 54.16 m³. Lo spedizioniere vuole sapere quale volume può ancora proporre.","q":"Quale volume resta disponibile?","a":["13.54 m³","13.61 m³","12.54 m³","121.86 m³"],"ex":"67.70 − 54.16 = 13.54 m³. Con i decimali si allineano le cifre dopo il punto.","ref":"Lezione 6.3"},{"k":"tf","q":"Quantità occupata + capacità disponibile = capacità totale.","v":true,"ex":"È il controllo da fare a ogni calcolo di capacità disponibile.","ref":"Lezione 6.3"},{"k":"num","q":"Una scaffalatura di 100 ubicazioni è occupata al 60 %. Si sistemano 15 palette in più. Qual è il nuovo tasso d’occupazione in %?","n":75,"tol":0,"u":"%","ex":"60 occupate + 15 = 75. 75 ÷ 100 × 100 = 75 %.","ref":"Lezione 6.4"},{"k":"num","q":"Un deposito di 100 ubicazioni contiene 75 palette. Lo si amplia di 50 ubicazioni. Qual è il nuovo tasso d’occupazione in %?","n":50,"tol":0,"u":"%","ex":"Sempre 75 palette, ma 150 ubicazioni: 75 ÷ 150 × 100 = 50 %.","ref":"Lezione 6.4"},{"k":"case","s":"Il deposito di Distrivaud conta 500 ubicazioni, occupate all’80 %. A fine giornata 160 palette partono in spedizione e liberano le loro ubicazioni.","q":"Qual è il nuovo tasso d’occupazione?","a":["48 %","64 %","32 %","52 %"],"ex":"Partenza: 500 × 0.80 = 400. Dopo la spedizione: 400 − 160 = 240. 240 ÷ 500 × 100 = 48 %.","ref":"Lezione 6.4"},{"k":"case","s":"Una scaffalatura di 240 ubicazioni è occupata al 75 %. In mattinata si sistemano 30 palette ricevute e 12 palette partono verso la produzione.","q":"Qual è il tasso d’occupazione a mezzogiorno?","a":["82.5 %","75.0 %","93.0 %","67.5 %"],"ex":"Partenza: 240 × 0.75 = 180. 180 + 30 − 12 = 198. 198 ÷ 240 × 100 = 82.5 %.","ref":"Lezione 6.4"},{"k":"qcm","q":"Un collega scrive «75 % + 15 palette = 90 %». Qual è il suo errore?","a":["Aggiunge un numero di palette a una percentuale","Dimentica di moltiplicare per 100 il risultato finale","Avrebbe dovuto sottrarre le 15 palette dal totale","Avrebbe dovuto dividere il tasso per 15 palette"],"ex":"Si torna alle quantità reali, si aggiorna, poi si ricalcola il tasso.","ref":"Lezione 6.4"},{"k":"order","q":"Metta in ordine il calcolo del tasso dopo un movimento di stock.","a":["Trovare la quantità occupata alla partenza","Aggiungere le entrate e sottrarre le uscite","Dividere per la capacità totale","Moltiplicare per 100"],"ex":"Tornare alle quantità, aggiornare, ricalcolare il tasso.","ref":"Lezione 6.4"},{"k":"match","q":"Abbini ogni grandezza al suo calcolo.","p":[["Tasso d’occupazione","Occupato ÷ capacità totale × 100"],["Tasso libero","100 % − tasso d’occupazione"],["Capacità disponibile","Capacità totale − occupato"],["Tasso di carico","Quantità caricata ÷ capacità massima × 100"]],"ex":"Tasso: in %. Capacità disponibile: in quantità reale (ubicazioni, kg, m³, L).","ref":"Lezione 6.3"},{"k":"odd","q":"Trovi l’intruso: quale di questi eventi fa CALARE il tasso d’occupazione senza che esca alcuna paletta?","a":["Ampliamento del deposito di 50 ubicazioni","Ricevimento di 20 palette","Ritorno di un cliente rimesso in stock","Sistemazione di una consegna"],"ex":"Un ampliamento cambia il totale (il denominatore), non lo stock. Gli altri tre fanno salire il tasso.","ref":"Lezione 6.4"},{"k":"case","s":"Un semirimorchio offre 33 posti paletta. Il carrellista ne ha caricati 27 e il disponente gli chiede il tasso di carico, arrotondato al decimo.","q":"Qual è il tasso di carico?","a":["81.8 %","18.2 %","82.0 %","122.2 %"],"ex":"27 ÷ 33 × 100 = 81.81… → 81.8 %.","ref":"Lezione 6.2"},{"k":"multi","q":"Si amplia un deposito senza spostare palette. Che cosa è vero?","good":["La capacità totale aumenta","La quantità stoccata non cambia","Il tasso d’occupazione cala"],"bad":["Alcune palette escono dallo stock","Il tasso libero cala"],"ex":"Un ampliamento cambia il denominatore, non lo stock: il tasso d’occupazione cala e il tasso libero sale.","ref":"Lezione 6.4"},{"k":"fill","q":"Un ampliamento del deposito cambia il ___, non la quantità stoccata.","a":["totale delle ubicazioni","numero di palette","peso stoccato","tasso di servizio"],"ex":"Cambia il denominatore (capacità totale); lo stock resta lo stesso.","ref":"Lezione 6.4"},{"k":"num","q":"Una zona di stoccaggio a terra misura 1’200 m². 900 m² sono occupati. Qual è il tasso d’occupazione in %?","n":75,"tol":0,"u":"%","ex":"900 ÷ 1’200 × 100 = 75 %.","ref":"Lezione 6.1"},{"k":"case","s":"È annunciato un ricevimento di 40 palette. La scaffalatura di 300 ubicazioni è occupata al 90 %. Il magazziniere deve dire al vettore se tutta la consegna ci sta.","q":"Che cosa risponde?","a":["No: 30 posti liberi, ne mancano 10","Sì: 30 posti liberi, ne restano 20","No: 270 posti liberi, ne mancano 230","Sì: 40 posti liberi, giusto abbastanza"],"ex":"Libere: 300 × 0.10 = 30 ubicazioni. 40 − 30 = 10 palette non trovano posto.","ref":"Lezione 6.3"}]},{"code":"Mod. 7","t":"Palettizzazione e ottimizzazione","g":"Calcolare quanti colli stanno su una paletta senza superare altezza e peso","col":"coral","ic":"pallet","ch":[{"k":"qcm","q":"Quali sono le dimensioni di una paletta EUR?","a":["1’200 × 800 mm","1’200 × 1’000 mm","1’000 × 800 mm","1’200 × 1’200 mm"],"ex":"Paletta EUR: 1’200 × 800 mm. Paletta industriale: 1’200 × 1’000 mm.","ref":"Lezione 7.1"},{"k":"qcm","q":"Quali sono le dimensioni di una paletta industriale?","a":["1’200 × 1’000 mm","1’200 × 800 mm","1’000 × 600 mm","800 × 600 mm"],"ex":"Paletta industriale: 1’200 × 1’000 mm.","ref":"Lezione 7.1"},{"k":"num","q":"Quanti cartoni di 400 × 200 mm stanno per strato su una paletta EUR?","n":12,"tol":0,"u":"cartoni","ex":"1’200 ÷ 400 = 3 e 800 ÷ 200 = 4: 3 × 4 = 12. Nell’altro senso: 6 × 2 = 12. Controllo: 960’000 ÷ 80’000 = 12, strato completo.","ref":"Lezione 7.1"},{"k":"case","s":"Il preparatore di Logipack deve palettizzare cartoni di 300 × 400 mm su una paletta EUR. Esita sul senso da dare ai cartoni.","q":"Quanti cartoni per strato al massimo?","a":["8 cartoni","6 cartoni","7 cartoni","10 cartoni"],"ex":"300 sulla lunghezza: 4 × 2 = 8. 400 sulla lunghezza: 3 × 2 = 6. Si tiene l’orientamento migliore: 8 cartoni.","ref":"Lezione 7.1"},{"k":"num","q":"Quanti cartoni di 600 × 400 mm stanno per strato su una paletta EUR?","n":4,"tol":0,"u":"cartoni","ex":"600 sulla lunghezza: 2 × 2 = 4. 400 sulla lunghezza: 3 × 1 = 3. Massimo: 4 cartoni.","ref":"Lezione 7.1"},{"k":"case","s":"Presso Distrivaud si caricano cartoni di 400 × 300 mm su palette industriali di 1’200 × 1’000 mm. L’apprendista calcola lo strato migliore.","q":"Quanti cartoni per strato al massimo?","a":["9 cartoni","10 cartoni","8 cartoni","12 cartoni"],"ex":"400 sulla lunghezza: 3 × 3 = 9 (1’000 ÷ 300 = 3.33 → 3). 300 sulla lunghezza: 4 × 2 = 8. Massimo: 9. I 10 cartoni della superficie sono un massimo teorico impossibile da raggiungere qui.","ref":"Lezione 7.1"},{"k":"tf","q":"Questo piano mostra uno strato completo: la paletta EUR è interamente coperta da 12 cartoni di 400 × 200 mm.","v":true,"img":"couche12","ex":"3 × 4 = 12 cartoni; 12 × 80’000 mm² = 960’000 mm², cioè tutta la superficie della paletta.","ref":"Lezione 7.1"},{"k":"tf","q":"Se 800 ÷ 300 = 2.66, si arrotonda a 3 cartoni sulla larghezza.","v":false,"ex":"Si arrotonda sempre per difetto: un pezzo di cartone non conta, quindi 2.","ref":"Lezione 7.1"},{"k":"tf","q":"La superficie della paletta divisa per la superficie di un cartone dà un massimo teorico.","v":true,"ex":"Non si può mai fare meglio. Se lo si raggiunge, lo strato è riempito perfettamente.","ref":"Lezione 7.1"},{"k":"pickimg","q":"Quale piano di strato mostra l’orientamento migliore di cartoni di 300 × 400 mm su una paletta EUR?","a":["couche8","couche6","couche7"],"ex":"300 sulla lunghezza: 4 × 2 = 8 cartoni. L’altro senso dà solo 6 cartoni.","ref":"Lezione 7.1"},{"k":"order","q":"Metta in ordine il calcolo dei cartoni per strato.","a":["Mettere tutte le dimensioni in mm","Dividere lunghezza e larghezza della paletta per quelle del cartone","Arrotondare per difetto ogni risultato","Moltiplicare i due numeri","Girare il cartone e tenere l’orientamento migliore"],"ex":"Lunghezza per lunghezza, larghezza per larghezza, arrotondamento per difetto, poi moltiplicare. Provare i due sensi.","ref":"Lezione 7.1"},{"k":"num","q":"Altezza massima: 1’350 mm. Paletta vuota: 150 mm. Cartoni: 300 mm d’altezza. Quanti strati si possono posare?","n":4,"tol":0,"u":"strati","img":"hauteur","ex":"1’350 − 150 = 1’200 mm. 1’200 ÷ 300 = 4 strati.","ref":"Lezione 7.2"},{"k":"case","s":"Il vano della scaffalatura di Stockalp accetta carichi alti al massimo 1’800 mm, paletta EUR (144 mm) compresa. I cartoni sono alti 250 mm.","q":"Quanti strati si possono posare?","a":["6 strati","7 strati","8 strati","5 strati"],"ex":"1’800 − 144 = 1’656 mm. 1’656 ÷ 250 = 6.62 → 6 strati (arrotondamento per difetto).","ref":"Lezione 7.2"},{"k":"case","s":"Altezza massima 1’600 mm, paletta vuota 150 mm, cartoni di 200 mm. Un collega annuncia «1’600 ÷ 200 = 8 strati». Controlla il suo calcolo.","q":"Quanti strati si possono posare realmente?","a":["7 strati","8 strati","7.25 strati","6 strati"],"ex":"Ha dimenticato la paletta vuota: 1’600 − 150 = 1’450 mm; 1’450 ÷ 200 = 7.25 → 7 strati.","ref":"Lezione 7.2"},{"k":"num","q":"Una paletta riceve 12 cartoni per strato su 6 strati. Quanti cartoni porta?","n":72,"tol":0,"u":"cartoni","ex":"12 × 6 = 72 cartoni.","ref":"Lezione 7.2"},{"k":"tf","q":"Se il calcolo dà 6.9 strati, si posano 7 strati.","v":false,"ex":"Si tengono solo gli strati completi: 6 strati. Il settimo supererebbe il limite.","ref":"Lezione 7.2"},{"k":"num","q":"Una paletta riceve 10 cartoni per strato su 4 strati. Qual è la sua capacità?","n":40,"tol":0,"u":"cartoni","ex":"10 × 4 = 40 cartoni.","ref":"Lezione 7.3"},{"k":"case","s":"Una commissione di 130 cartoni deve partire stasera. Ogni paletta riceve 10 cartoni per strato su 4 strati. Il preparatore deve riservare palette vuote.","q":"Quante palette bisogna preparare?","a":["4 palette","3 palette","5 palette","13 palette"],"ex":"Capacità: 40 cartoni. 130 ÷ 40 = 3.25 → 4 palette necessarie (arrotondamento per eccesso: anche l’ultima, incompleta, deve partire).","ref":"Lezione 7.3"},{"k":"num","q":"130 cartoni, 40 cartoni per paletta: quante palette saranno complete?","n":3,"tol":0,"u":"palette","ex":"130 ÷ 40 = 3.25 → 3 palette complete (arrotondamento per difetto).","ref":"Lezione 7.3"},{"k":"num","q":"130 cartoni, 40 cartoni per paletta: quanti cartoni andranno sull’ultima paletta?","n":10,"tol":0,"u":"cartoni","ex":"130 − 3 × 40 = 10 cartoni.","ref":"Lezione 7.3"},{"k":"case","s":"Logimax deve spedire 500 cartoni. Una paletta riceve 12 cartoni per strato su 5 strati. Il caposquadra riserva le palette e lo spazio nel camion.","q":"Quante palette sono necessarie?","a":["9 palette","8 palette","10 palette","7 palette"],"ex":"Capacità: 12 × 5 = 60. 500 ÷ 60 = 8.33 → 9 palette necessarie.","ref":"Lezione 7.3"},{"k":"case","s":"Stessa commissione di 500 cartoni, palette da 60 cartoni (12 per strato su 5 strati). Il preparatore vuole sapere che cosa metterà sull’ultima paletta.","q":"Quanti cartoni andranno sull’ultima paletta?","a":["20 cartoni","40 cartoni","60 cartoni","8 cartoni"],"ex":"8 palette complete: 8 × 60 = 480. 500 − 480 = 20 cartoni.","ref":"Lezione 7.3"},{"k":"sort","q":"In quale senso bisogna arrotondare?","c":["Per eccesso","Per difetto"],"it":[["Palette necessarie per una commissione",0],["Palette complete",1],["Strati sotto un’altezza massima",1],["Cartoni sulla lunghezza della paletta",1],["Cartoni caricabili secondo il peso",1],["Preparatori da impiegare per una commissione",0]],"ex":"Per eccesso quando tutto deve partire o essere trattato. Per difetto quando un limite non dev’essere superato.","ref":"Lezione 7.3"},{"k":"num","q":"Massa totale massima (paletta compresa): 500 kg. Paletta vuota: 20 kg. Cartone: 10 kg. Lo spazio permette 50 cartoni. Quanti cartoni si possono caricare?","n":48,"tol":0,"u":"cartoni","ex":"500 − 20 = 480 kg; 480 ÷ 10 = 48. Lo spazio ne permette 50: si tiene il più piccolo, 48.","ref":"Lezione 7.4"},{"k":"case","s":"Secondo lo spazio la paletta di Logipack può accogliere 60 cartoni. La massa totale non deve superare 800 kg, paletta compresa. Paletta vuota: 25 kg; cartone: 14 kg.","q":"Quanti cartoni si possono caricare realmente?","a":["55 cartoni","60 cartoni","57 cartoni","56 cartoni"],"ex":"800 − 25 = 775 kg; 775 ÷ 14 = 55.36 → 55. Spazio: 60. Si tiene il più piccolo: 55 cartoni.","ref":"Lezione 7.4"},{"k":"case","s":"La scaffalatura accetta 1’000 kg di carico posato sulla paletta (paletta non compresa). I cartoni pesano 18 kg e lo spazio permette 64 cartoni.","q":"Quanti cartoni si possono caricare?","a":["55 cartoni","56 cartoni","54 cartoni","64 cartoni"],"ex":"Il limite non comprende la paletta: 1’000 ÷ 18 = 55.56 → 55 cartoni (meno dei 64 dello spazio).","ref":"Lezione 7.4"},{"k":"qcm","q":"Lo spazio permette 50 cartoni e il peso ne permette 48. Quanti cartoni si caricano?","a":["48 cartoni","50 cartoni","49 cartoni","98 cartoni"],"ex":"Due limiti: decide il più piccolo.","ref":"Lezione 7.4"},{"k":"match","q":"Abbini ogni grandezza alla sua formula.","p":[["Numero di strati","(Altezza max − paletta vuota) ÷ altezza di un cartone"],["Capacità di una paletta","Cartoni per strato × numero di strati"],["Massa totale","Paletta vuota + cartoni × massa di un cartone"],["Ultima paletta","Totale − palette complete × capacità"]],"ex":"Formule delle lezioni da 7.2 a 7.4.","ref":"Lezione 7.4"},{"k":"odd","q":"Trovi l’intruso: quale di questi elementi NON limita l’altezza di una paletta carica?","a":["Il peso di un cartone","Il vano della scaffalatura","L’altezza interna del camion","Le istruzioni del cliente"],"ex":"Il peso limita il carico, non l’altezza.","ref":"Lezione 7.2"},{"k":"multi","q":"Quali sono errori frequenti nel calcolo degli strati?","good":["Dimenticare l’altezza della paletta vuota","Arrotondare per eccesso","Confondere altezza e lunghezza del cartone"],"bad":["Arrotondare per difetto il numero di strati","Togliere la paletta vuota dall’altezza massima"],"ex":"Togliere la paletta, dividere per l’altezza di un cartone, arrotondare per difetto.","ref":"Lezione 7.2"},{"k":"case","s":"Cartoni di 400 × 300 × 250 mm (h), 12 kg ciascuno, su paletta EUR di 144 mm e 25 kg. Altezza max 1’400 mm, massa totale max 1’000 kg paletta compresa.","q":"Quanti cartoni si possono caricare?","a":["40 cartoni","81 cartoni","48 cartoni","45 cartoni"],"ex":"Strato: 8. Strati: (1’400 − 144) ÷ 250 = 5.02 → 5. Spazio: 40. Peso: 975 ÷ 12 → 81. Il più piccolo: 40 cartoni.","ref":"Lezione 7.4"}]},{"code":"Mod. 8","t":"Carico utile e ripartizione","g":"Verificare che un carico rispetti il carico utile del veicolo","col":"amber","ic":"truckw","ch":[{"k":"qcm","q":"Come si calcola il carico utile di un veicolo?","a":["Peso totale autorizzato − peso a vuoto","Peso a vuoto − peso totale autorizzato","Peso totale autorizzato + peso a vuoto","Peso a vuoto − carico trasportato"],"ex":"Carico utile = peso totale autorizzato − peso a vuoto.","ref":"Lezione 8.1"},{"k":"num","q":"Un camion ha un peso totale autorizzato di 18 t e un peso a vuoto di 8 t. Qual è il suo carico utile in tonnellate?","n":10,"tol":0,"u":"t","ex":"18 − 8 = 10 t.","ref":"Lezione 8.1"},{"k":"num","q":"Carico utile: 10’000 kg. Il camion trasporta 8 palette da 500 kg. Quale carico resta disponibile in kg?","n":6000,"tol":0,"u":"kg","ex":"8 × 500 = 4’000 kg; 10’000 − 4’000 = 6’000 kg.","ref":"Lezione 8.1"},{"k":"case","s":"Il carico utile del camion è di 10’000 kg e porta già 4’000 kg. Un collega toglie ancora il peso a vuoto del camion (8’000 kg) e conclude che non resta niente.","q":"Che cosa gli risponde?","a":["Falso: il carico utile deduce già il peso a vuoto","Corretto: il peso del camion si toglie a ogni calcolo","Falso: bisogna invece aggiungere il peso a vuoto","Corretto: restano allora esattamente 2’000 kg"],"ex":"Il peso del veicolo non entra mai nel calcolo del carico: è già dedotto dal carico utile. Restano 6’000 kg.","ref":"Lezione 8.1"},{"k":"tf","q":"Il peso del veicolo a vuoto entra nel calcolo del carico disponibile.","v":false,"ex":"È già dedotto nel carico utile.","ref":"Lezione 8.1"},{"k":"num","q":"Un furgone ha un carico utile di 3.5 t. Trasporta 2’150 kg. Quale carico resta disponibile in kg?","n":1350,"tol":0,"u":"kg","ex":"3.5 t = 3’500 kg. 3’500 − 2’150 = 1’350 kg.","ref":"Lezione 8.1"},{"k":"num","q":"Un camion ha un carico utile di 12’000 kg. Trasporta 9’000 kg. Qual è il suo tasso di carico in %?","n":75,"tol":0,"u":"%","ex":"9’000 ÷ 12’000 × 100 = 75 %.","ref":"Lezione 8.2"},{"k":"num","q":"Un camion ha un carico utile di 20’000 kg. È caricato all’85 %. Quale massa trasporta in kg?","n":17000,"tol":0,"u":"kg","ex":"20’000 × 85 ÷ 100 = 17’000 kg.","ref":"Lezione 8.2"},{"k":"case","s":"Il camion di TransLéman ha un carico utile di 24’000 kg. Stasera parte con 17’000 kg. Il disponente annota il tasso di carico, arrotondato al decimo.","q":"Qual è il tasso di carico?","a":["70.8 %","70.9 %","141.2 %","29.2 %"],"ex":"17’000 ÷ 24’000 × 100 = 70.83… → 70.8 %.","ref":"Lezione 8.2"},{"k":"qcm","q":"Un camion è caricato al 75 % del suo carico utile. Quale quota resta libera?","a":["25 %","75 %","33 %","125 %"],"ex":"100 % − 75 % = 25 %.","ref":"Lezione 8.2"},{"k":"tf","q":"Se si divide il carico utile per il carico trasportato, si ottiene un risultato superiore al 100 %.","v":true,"ex":"È il segno di una divisione invertita: si divide il carico trasportato per il carico utile.","ref":"Lezione 8.2"},{"k":"num","q":"Restano 2’000 kg di carico disponibile. Ogni paletta pesa 450 kg. Quante palette si possono ancora caricare?","n":4,"tol":0,"u":"palette","ex":"2’000 ÷ 450 = 4.44 → 4 palette. Controllo: 4 × 450 = 1’800 kg; 5 × 450 = 2’250 kg (sovraccarico).","ref":"Lezione 8.3"},{"k":"case","s":"Un camion di corriere ha ancora 3’000 kg di carico disponibile. I colli da caricare pesano 35 kg ciascuno. L’autista vuole prenderne il massimo.","q":"Quanti colli può ancora caricare?","a":["85 colli","86 colli","84 colli","87 colli"],"ex":"3’000 ÷ 35 = 85.71 → 85 colli. Arrotondare a 86 farebbe superare il carico utile (86 × 35 = 3’010 kg).","ref":"Lezione 8.3"},{"k":"tf","q":"Se il calcolo dà 4.6 palette, si possono ancora caricare 5 palette.","v":false,"ex":"Sempre per difetto: 4 palette. Un sovraccarico non è mai tollerato.","ref":"Lezione 8.3"},{"k":"qcm","q":"Perché si arrotonda sempre per difetto il numero di unità trasportabili?","a":["Un’unità in più farebbe superare il carico utile","Le calcolatrici non gestiscono i decimali","Il cliente paga solo le palette intere","È la regola matematica di ogni arrotondamento"],"ex":"Si cerca che cosa può ancora salire senza superare un limite.","ref":"Lezione 8.3"},{"k":"sort","q":"In quale senso bisogna arrotondare?","c":["Per eccesso","Per difetto"],"it":[["Palette che possono ancora salire sul camion",1],["Colli supplementari nel furgone",1],["Palette necessarie per spedire una commissione",0],["Tragitti necessari per consegnare 50 t con un camion da 12 t",0],["Cartoni caricabili sotto un limite di peso",1]],"ex":"Limite da rispettare: per difetto. Tutto deve partire: per eccesso.","ref":"Lezione 8.3"},{"k":"num","q":"Un camion trasporta 6 palette da 800 kg e 4 palette da 600 kg. Qual è il carico trasportato in kg?","n":7200,"tol":0,"u":"kg","ex":"6 × 800 = 4’800; 4 × 600 = 2’400; 4’800 + 2’400 = 7’200 kg.","ref":"Lezione 8.4"},{"k":"case","s":"Il camion di Logimax ha un carico utile di 12’000 kg. Trasporta già 6 palette da 800 kg e 4 palette da 600 kg. Si vogliono aggiungere palette da 900 kg.","q":"Quante palette da 900 kg può ancora caricare?","a":["5 palette","6 palette","13 palette","3 palette"],"ex":"Trasportato: 7’200 kg. Disponibile: 4’800 kg. 4’800 ÷ 900 = 5.33 → 5 palette.","ref":"Lezione 8.4"},{"k":"case","s":"Un semirimorchio di Transvalor (carico utile 18’000 kg) porta 10 palette da 750 kg e 8 palette da 520 kg. Il disponente controlla il tasso di carico.","q":"Qual è il tasso di carico, arrotondato al decimo?","a":["64.8 %","35.2 %","63.0 %","154.4 %"],"ex":"7’500 + 4’160 = 11’660 kg. 11’660 ÷ 18’000 × 100 = 64.8 %.","ref":"Lezione 8.4"},{"k":"case","s":"Un furgone (carico utile 1’200 kg) trasporta 15 colli da 32 kg e 6 colli da 48 kg. Il fattorino vuole aggiungere colli da 25 kg per un ultimo cliente.","q":"Quanti colli da 25 kg può ancora caricare?","a":["17 colli","18 colli","48 colli","30 colli"],"ex":"Trasportato: 480 + 288 = 768 kg. Disponibile: 432 kg. 432 ÷ 25 = 17.28 → 17 colli.","ref":"Lezione 8.4"},{"k":"order","q":"Metta in ordine il metodo per un carico misto.","a":["Calcolare il peso di ogni gruppo di palette","Sommare i gruppi","Sottrarre il totale dal carico utile","Dividere per il peso di una paletta e arrotondare per difetto"],"ex":"Gruppo per gruppo, sommare, sottrarre dal carico utile, poi dividere e arrotondare per difetto.","ref":"Lezione 8.4"},{"k":"match","q":"Abbini ogni nozione alla sua definizione.","p":[["Peso totale autorizzato","Peso massimo del veicolo carico"],["Peso a vuoto","Peso del veicolo senza carico"],["Carico utile","Peso massimo di merci trasportabili"],["Carico disponibile","Carico utile − carico già trasportato"]],"ex":"Carico utile = peso totale autorizzato − peso a vuoto; carico disponibile = carico utile − carico trasportato.","ref":"Lezione 8.1"},{"k":"multi","q":"Quali sono le buone pratiche di ripartizione dei carichi?","good":["Mettere le palette pesanti in basso","Mettere le palette pesanti verso il centro del pianale","Equilibrare il peso tra davanti e dietro","Equilibrare il peso tra sinistra e destra"],"bad":["Mettere le palette pesanti dietro per scaricare in fretta","Posare le palette leggere sotto quelle pesanti"],"ex":"Rispettare il carico utile non basta: la ripartizione fa parte di un carico sicuro.","ref":"Lezione 8.4"},{"k":"odd","q":"Trovi l’intruso: quale NON è un errore?","a":["Controllare aggiungendo un’unità in più","Dimenticare un gruppo di palette nella somma","Moltiplicare tutte le palette per un solo peso","Arrotondare per eccesso le palette in più"],"ex":"Aggiungere un’unità in più per verificare che superi il carico disponibile è il controllo corretto.","ref":"Lezione 8.4"},{"k":"case","s":"Un furgone ha un carico utile di 7.5 t. Trasporta già 5’600 kg di materiale. Il magazziniere vuole sapere quale carico può ancora aggiungere.","q":"Quale carico resta disponibile?","a":["1’900 kg","2’900 kg","190 kg","13’100 kg"],"ex":"7.5 t = 7’500 kg. 7’500 − 5’600 = 1’900 kg. Trappola: mescolare kg e tonnellate.","ref":"Lezione 8.1"},{"k":"fill","q":"Carico utile = peso totale autorizzato − ___.","a":["peso a vuoto","carico disponibile","carico trasportato","peso delle palette"],"ex":"Il carico utile si ricava dai documenti del veicolo.","ref":"Lezione 8.1"},{"k":"case","s":"Un camion con 10 t di carico utile deve partire con 14 palette da 680 kg ciascuna. Il caporampa controlla il carico prima della partenza.","q":"Il carico è conforme?","a":["Sì: 9’520 kg, restano 480 kg","No: 9’520 kg, supera di 480 kg","Sì: 8’400 kg, restano 1’600 kg","No: 14 palette superano sempre 10 t"],"ex":"14 × 680 = 9’520 kg ≤ 10’000 kg: conforme (95.2 %). Restano 480 kg.","ref":"Lezione 8.2"},{"k":"num","q":"Un camion ha un peso totale autorizzato di 26 t e un peso a vuoto di 11.2 t. Qual è il suo carico utile in kg?","n":14800,"tol":0,"u":"kg","img":"charge","ex":"26 − 11.2 = 14.8 t = 14’800 kg.","ref":"Lezione 8.1"},{"k":"case","s":"Il furgone di un fattorino (carico utile 1’000 kg) porta già 620 kg. Dall’ultimo cliente gli si chiede di riprendere 9 colli da 45 kg.","q":"Che cosa può fare?","a":["Prendere 8 colli: 1 in più supererebbe di 25 kg","Prendere i 9 colli: il carico resta sotto 1’000 kg","Prendere solo 7 colli, per sicurezza","Non prendere niente: il furgone è già pieno"],"ex":"Disponibile: 1’000 − 620 = 380 kg. 380 ÷ 45 = 8.44 → 8 colli. Con 9 colli: 620 + 405 = 1’025 kg, sovraccarico di 25 kg.","ref":"Lezione 8.3"}]}];
